using System;
using System.Globalization;
using System.IO;
using NUnit.Framework;
using CursedDeck.Meta;
using CursedDeck.Run;
using CursedDeck.Core;
using CursedDeck.Data;
using UnityEngine;
namespace CursedDeck.MetaTests
{
    public sealed class MetaTests
    {
        private static DateTime Day(int day)=>new DateTime(2026,10,day,0,0,0,DateTimeKind.Utc);
        private static void Award(MetaProfile p,int day=1,bool won=true,int seconds=100){p.Begin(DailyRun.Seed(Day(day)),"classic",DailyRun.DateKey(Day(day)),Day(day));for(int i=0;i<9;i++)p.Active.Observe(i/3+1,i%3+1,100+i,10+i,won);p.Finish(won,Day(day).AddSeconds(seconds),new MetaRules());}
        [Test] public void DailySeedUsesUtcDateNotTimeAndChangesAcrossDates(){Assert.That(DailyRun.Seed(Day(1)),Is.EqualTo(DailyRun.Seed(Day(1).AddHours(23))));Assert.That(DailyRun.Seed(Day(1)),Is.Not.EqualTo(DailyRun.Seed(Day(2))));Assert.Throws<ArgumentException>(()=>DailyRun.Seed(DateTime.Now));}
        [Test] public void UnlocksGateSpendExactlyOnceAndNeverAllowDebt(){var p=new MetaProfile();var r=new MetaRules();Assert.That(p.IsUnlocked("classic"));Assert.That(p.TryUnlock("red-deck",r),Is.False);Assert.Throws<InvalidOperationException>(()=>p.Begin(1,"red-deck",null,Day(1)));Award(p);int before=p.SoulShards;Assert.That(p.TryUnlock("red-deck",r));Assert.That(p.SoulShards,Is.EqualTo(before-20));Assert.That(p.TryUnlock("red-deck",r),Is.False);Assert.That(p.TryUnlock("unknown",r),Is.False);for(int i=1;i<5;i++)Assert.That(p.TryUnlock(MetaUnlocks.Ids[i],r));Assert.That(p.TryUnlock(MetaUnlocks.Ids[5],r),Is.False);Assert.That(p.SoulShards,Is.GreaterThanOrEqualTo(0));}
        [Test] public void FinalizingIsIdempotentAndStatsUseRunTotalsAndFastestWinOnly(){var p=new MetaProfile();Award(p);Assert.That(p.SoulShards,Is.EqualTo(67));Assert.That(p.BestScore,Is.EqualTo(936));Assert.That(p.LongestChain,Is.EqualTo(18));Assert.That(p.Wins,Is.EqualTo(1));Assert.That(p.Finish(true,Day(1).AddMinutes(10),new MetaRules()),Is.False);Award(p,2,false,1);Assert.That(p.FastestRunSeconds,Is.EqualTo(100));Award(p,3,true,50);Assert.That(p.FastestRunSeconds,Is.EqualTo(50));Assert.That(p.Wins,Is.EqualTo(2));}
        [Test] public void DailyStreakRequiresConsecutiveWinsAndDoesNotFarmSameOrOlderDate(){var p=new MetaProfile();Award(p,1);Award(p,2);Assert.That(p.DailyStreak,Is.EqualTo(2));Award(p,2);Award(p,1);Assert.That(p.DailyStreak,Is.EqualTo(2));Award(p,4);Assert.That(p.DailyStreak,Is.EqualTo(1));Award(p,5,false);Assert.That(p.DailyStreak,Is.EqualTo(1));Award(p,6);Assert.That(p.DailyStreak,Is.EqualTo(1));}
        [Test] public void DailyForcesClassicAndCorrectSeedAndDate(){var p=new MetaProfile();Award(p);p.TryUnlock("red-deck",new MetaRules());Assert.Throws<InvalidOperationException>(()=>p.Begin(1,"classic","2026-10-01",Day(1)));Assert.Throws<InvalidOperationException>(()=>p.Begin(DailyRun.Seed(Day(1)),"red-deck","2026-10-01",Day(1)));}
        [Test] public void ShareHasStableGridAndInvariantScore(){var old=CultureInfo.CurrentCulture;try{CultureInfo.CurrentCulture=new CultureInfo("fr-FR");string s=DailyRun.Share("2026-10-01",42,1234.5m,4,false);Assert.That(s,Is.EqualTo("Cursed Deck Daily 2026-10-01 END\n\U0001F7E8\U0001F7E8\U0001F7E8\n\U0001F7E8\u2B1B\u2B1B\n\u2B1B\u2B1B\u2B1B\nScore 1234.5 | 4/9\nSeed 42"));}finally{CultureInfo.CurrentCulture=old;}}
        [Test] public void JsonRoundTripRetainsUnlocksStatsActiveSessionAndReceipts(){var p=new MetaProfile();Award(p);p.TryUnlock("red-deck",new MetaRules());string json=MetaStore.ToJson(p);var restored=MetaStore.FromJson(json);Assert.That(MetaStore.ToJson(restored),Is.EqualTo(json));Assert.That(restored.Finish(true,Day(2),new MetaRules()),Is.False);Assert.That(restored.IsUnlocked("red-deck"));}
        [Test] public void AtomicProfileSaveRecoversBackupAndPreservesCorruption(){string dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));try{var store=new MetaStore(Path.Combine(dir,"meta.json"));var p=store.Load(out _);store.Save(p);Award(p);store.Save(p);File.WriteAllText(store.Path,"bad");var restored=store.Load(out string warning);Assert.That(restored.SoulShards,Is.EqualTo(0));Assert.That(warning,Does.Contain("backup"));Assert.That(File.ReadAllText(store.Path),Is.EqualTo("bad"));}finally{if(Directory.Exists(dir))Directory.Delete(dir,true);}}
        [Test] public void RedDeckBonusStacksWithRedVelvetAndSurvivesReplay(){var bonus=new RelicSpec("red-deck-bonus",RelicKind.RedVelvet,0,multiplier:1.1m);var velvet=new RelicSpec("red-velvet",RelicKind.RedVelvet,100,multiplier:2);var run=new RunController(42,new[]{bonus,velvet},startingRelics:new[]{bonus,velvet});var state=new RunState(1);state.Acquire(bonus);state.Acquire(velvet);var effects=new RelicManager(state);var round=new RoundSession(WinnableBoardGenerator.Generate(1).CreateGame(),100000,23,effects:effects);round.Start();Assert.That(new ScoringPipeline().Evaluate(new ScoreContext(new CardModel(Rank.Three,Suit.Hearts),1),effects),Is.EqualTo(220));Assert.That(new ScoringPipeline().Evaluate(new ScoreContext(new CardModel(Rank.Three,Suit.Clubs),1),effects),Is.EqualTo(100));Assert.That(RunController.FromJson(run.ToJson()).ToJson(),Is.EqualTo(run.ToJson()));}
        [Test] public void FiveAuthoredUnlocksHaveExpectedScoringStages(){var data=Resources.Load<MetaDefinition>("CursedDeck/Meta");Assert.That(data.UnlockRelics.Length,Is.EqualTo(5));for(int i=0;i<5;i++){var spec=data.UnlockRelics[i].CreateSpec();Assert.That(spec.Id,Is.EqualTo(MetaUnlocks.Ids[i+1]));var run=new RunState(1);run.Acquire(spec);var manager=new RelicManager(run);var round=new RoundSession(WinnableBoardGenerator.Generate(42).CreateGame(),1000000,23,effects:manager);round.Start();var card=new CardModel(i==3?Rank.King:Rank.Three,i==0?Suit.Clubs:Suit.Hearts);decimal points=new ScoringPipeline().Evaluate(new ScoreContext(card,5),manager);Assert.That(points,Is.GreaterThan(200));}}
    }
}
